class SQL {
  private final java.util.Map<String, int[]> meta = new java.util.HashMap<>();
  private final java.util.Map<String, java.util.LinkedHashMap<Integer, String[]>> tables =
      new java.util.HashMap<>();

  public SQL(List<String> names, List<Integer> columns) {
    for (int i = 0; i < names.size(); i++) {
      meta.put(names.get(i), new int[] {columns.get(i), 1});
      tables.put(names.get(i), new java.util.LinkedHashMap<>());
    }
  }

  public boolean ins(String name, List<String> row) {
    int[] m = meta.get(name);
    if (m == null || m[0] != row.size()) return false;
    tables.get(name).put(m[1]++, row.toArray(new String[0]));
    return true;
  }

  public void rmv(String name, int rowId) {
    java.util.LinkedHashMap<Integer, String[]> t = tables.get(name);
    if (t != null) t.remove(rowId);
  }

  public String sel(String name, int rowId, int columnId) {
    java.util.LinkedHashMap<Integer, String[]> t = tables.get(name);
    if (t == null) return "<null>";
    String[] r = t.get(rowId);
    if (r == null || columnId < 1 || columnId > r.length) return "<null>";
    return r[columnId - 1];
  }

  public List<String> exp(String name) {
    List<String> res = new ArrayList<>();
    java.util.LinkedHashMap<Integer, String[]> t = tables.get(name);
    if (t == null) return res;
    for (java.util.Map.Entry<Integer, String[]> e : t.entrySet())
      res.add(e.getKey() + "," + String.join(",", e.getValue()));
    return res;
  }
}
